import PDFKit

/// Ejercicio de ejemplo (PDF vectorial recortado, Computer Modern) que la mini-hoja del onboarding y de Ajustes dibuja como enunciado.
enum SampleExercise {
    static let page: PDFPage? = {
        guard let data = Data(base64Encoded: b64), let doc = PDFDocument(data: data) else { return nil }
        return doc.page(at: 0)
    }()

    private static let b64 = ""
}
